SELECT l.id AS line_id, COALESCE(r.accepted_qty, 0) AS accepted_qty
FROM lines l LEFT JOIN (
 SELECT line_id, SUM(accepted) AS accepted_qty FROM receipts
 WHERE received_on <= DATE '2026-06-30' GROUP BY line_id
) r ON r.line_id = l.id ORDER BY l.id;

SELECT l.id AS line_id FROM lines l
WHERE NOT EXISTS (SELECT 1 FROM receipts r WHERE r.line_id=l.id
 AND r.received_on <= DATE '2026-06-30') ORDER BY l.id;

SELECT DISTINCT ON (product) product, price AS market_price FROM prices
WHERE currency='USD' AND unit='kg' AND priced_on <= DATE '2026-06-15'
ORDER BY product, priced_on DESC, id DESC;

SELECT id AS receipt_id,
 LAG(accepted) OVER (PARTITION BY line_id ORDER BY received_on, id) AS previous_accepted
FROM receipts WHERE received_on <= DATE '2026-06-30' ORDER BY id;

WITH a AS (
 SELECT line_id,SUM(accepted) AS qty FROM receipts
 WHERE received_on <= DATE '2026-06-30' GROUP BY line_id
)
SELECT l.id AS line_id, ROUND(100 * COALESCE(a.qty,0) / NULLIF(l.quantity,0),2) AS accepted_pct
FROM lines l LEFT JOIN a ON a.line_id=l.id ORDER BY l.id;

SELECT supplier_id,COUNT(*) AS order_count FROM orders
WHERE ordered_on <= DATE '2026-06-30' AND status <> 'cancelled'
GROUP BY supplier_id HAVING COUNT(*) >= 2 ORDER BY supplier_id;
